using System;
using System.Linq;
using System.Reflection;

class Program
{
    static void Main()
    {
        var home = Environment.GetFolderPath(Environment.SpecialFolder.UserProfile);
        var asm = Assembly.LoadFrom(
            Path.Combine(home, ".nuget/packages/modelcontextprotocol.core/1.4.0/lib/net9.0/ModelContextProtocol.Core.dll"));

        var types = new[] {
            "ModelContextProtocol.Server.McpServerToolAttribute",
            "ModelContextProtocol.Server.McpServerPromptAttribute",
            "ModelContextProtocol.Protocol.PromptMessage",
            "ModelContextProtocol.Protocol.ContentBlock",
            "ModelContextProtocol.Protocol.TextContentBlock",
            "ModelContextProtocol.Protocol.Role",
        };

        foreach (var name in types)
        {
            var t = asm.GetType(name);
            if (t == null) { Console.WriteLine($"{name}: NOT FOUND"); continue; }
            Console.WriteLine($"\n=== {t.FullName} (IsEnum={t.IsEnum}) ===");
            foreach (var c in t.GetConstructors())
                Console.WriteLine($"  ctor({string.Join(", ", c.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"))})");
            foreach (var p in t.GetProperties(BindingFlags.Public | BindingFlags.Instance))
                Console.WriteLine($"  {p.PropertyType.Name} {p.Name} {{get;{(p.CanWrite?"set;":"")}}}");
            if (t.IsEnum)
                foreach (var v in Enum.GetNames(t))
                    Console.WriteLine($"  {v}");
        }
    }
}
