arguments.old_str:
using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpServer.Prompts;

[McpServerPromptType]
public sealed class SummarizePrompt
{
    [McpServerPrompt("summarize"), Description("Generates a prompt that asks the model to summarize the given text.")]
    public static IList<PromptMessage> Summarize(
        [Description("The text to summarize.")] string text,
        [Description("Optional maximum number of sentences for the summary.")] string? maxSentences = null)
    {
        var constraint = maxSentences is not null
            ? $" Limit the summary to {maxSentences} sentences."
            : string.Empty;

        return
        [
            new PromptMessage
            {
                Role = Role.User,
                Content = new Content
                {
                    Type = "text",
                    Text = $"Please provide a concise summary of the following text.{constraint}\n\n{text}"
                }
            }
        ];
    }
}

